import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class CommentsConfigurationTest {

    @Test
    public void commentsConfigurationDefaultConstructorTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        assertTrue(commentsConfiguration.getAllComments().isEmpty());
    }

    @Test
    public void commentsConfigurationParametrizedConstructorTest() {
        Map<String, List<String>> commentsMap = new HashMap<>();
        commentsMap.put("Path1", Arrays.asList("comment1", "comment2"));
        commentsMap.put("Path2", Arrays.asList("comment1", "comment2", "comment3"));

        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(commentsMap);
        assertEquals(commentsConfiguration.getAllComments(), commentsMap);
    }

    @Test
    public void setCommentTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment("Path1", "comment1", "comment2");
        commentsConfiguration.setComment("Path2", "comment1", "comment2", "comment3");

        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("Path1", Arrays.asList("comment1", "comment2"));
        expectedComments.put("Path2", Arrays.asList("comment1", "comment2", "comment3"));

        assertEquals(commentsConfiguration.getAllComments(), expectedComments);
    }

    @Test
    public void getAllCommentsTest() {
        Map<String, List<String>> commentsMap = new HashMap<>();
        commentsMap.put("Path1", new ArrayList<>(Arrays.asList("comment1", "comment2")));
        commentsMap.put("Path2", new ArrayList<>(Arrays.asList("comment1", "comment2", "comment3")));

        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(commentsMap);
        assertEquals(commentsConfiguration.getAllComments(), commentsMap);
    }
